def pass_rate(runs):
    if not runs:
        return None
    return sum(r["status"] == "passed" for r in runs) / len(runs)

def slow_tests(runs, *, threshold=3.0):
    return [r["name"] for r in runs if r["duration"] > threshold]

print(slow_tests([{ "name": "checkout", "duration": 4.2}], threshold=4.0))

def failures(records):
    for record in records:
        if record["status"] == "failed":
            yield record

if __name__ == "__main__":
    print(list(failures([])))

from dataclasses import dataclass

@dataclass(frozen=True)
class TestResult:
    name: str
    status: str
    duration: float

def validate(result):
    if result.status not in {"passed", "failed", "skipped"}:
        raise ValueError("unknown status")
    if result.duration < 0:
        raise ValueError("negative duration")
    return result

exercise.tests:
assert validate_duration(0) == 0
assert validate_duration(4.5) == 4.5
for v in [-1, True, "4.5", None]:
    try:
        validate_duration(v)
    except ValueError:
        pass
    else:
        raise AssertionError(f"Expected ValueError for {v!r}")

